"""
Numerical demonstration of plethystic triviality of the shifted t-Schur basis.

Main identity demonstrated:

    S^t_lambda = phi_t(Q_lambda),     phi_t(p_n) = (1 - t^n) p_n  (n odd).

This script focuses on the *creation-part intertwining* that is the
computational heart of the theorem,

    qt_n = phi_t(q_n),

where:

  * q_n   are the one-row Schur Q-functions Q_(n), defined by the Newton
          recursion coming from the log-derivative of the generating kernel
          prod_i (1 + x_i z)/(1 - x_i z) = exp( sum_{r odd} (2/r) p_r z^r );
  * qt_n  are their t-deformations, built by feeding the t-deformed odd power
          sums (1 - t^{2k+1}) p_{2k+1} into the *same* recursion;
  * phi_t is the plethystic substitution p_{2k+1} -> (1 - t^{2k+1}) p_{2k+1}.

We work in the polynomial ring Lambda = Q(t)[X_0, X_1, X_2, ...], where the
variable X_k stands for the odd power sum p_{2k+1}.  Polynomials are stored as
dictionaries mapping monomials (tuples of (index, exponent) pairs) to sympy
coefficients in the field Q(t).  Everything is inlined and self-contained.

Requires: sympy (a standard symbolic-mathematics library).
"""

from __future__ import annotations

from typing import Dict, Tuple

import sympy as sp

# A monomial in the X_k is a canonical sorted tuple of (index, exponent) pairs.
Monomial = Tuple[Tuple[int, int], ...]
# A polynomial is a mapping monomial -> coefficient in Q(t).
Poly = Dict[Monomial, sp.Expr]

# The transcendental parameter t.
T: sp.Symbol = sp.symbols("t")


def poly_zero() -> Poly:
    """The zero polynomial."""
    return {}


def poly_one() -> Poly:
    """The constant polynomial 1 (empty monomial)."""
    return {(): sp.Integer(1)}


def poly_var(k: int) -> Poly:
    """The variable X_k = p_{2k+1}, as a degree-one monomial."""
    return {((k, 1),): sp.Integer(1)}


def poly_add(a: Poly, b: Poly) -> Poly:
    """Add two polynomials, dropping monomials whose coefficient cancels to 0."""
    out: Poly = dict(a)
    for mon, coeff in b.items():
        new = sp.cancel(out.get(mon, sp.Integer(0)) + coeff)
        if new == 0:
            out.pop(mon, None)
        else:
            out[mon] = new
    return out


def poly_scale(c: sp.Expr, a: Poly) -> Poly:
    """Multiply a polynomial by a scalar c in Q(t)."""
    c = sp.cancel(c)
    if c == 0:
        return poly_zero()
    return {mon: sp.cancel(c * coeff) for mon, coeff in a.items()}


def _mon_mul(m1: Monomial, m2: Monomial) -> Monomial:
    """Multiply two monomials by adding exponents index-by-index."""
    exps: Dict[int, int] = {}
    for idx, e in m1:
        exps[idx] = exps.get(idx, 0) + e
    for idx, e in m2:
        exps[idx] = exps.get(idx, 0) + e
    return tuple(sorted((idx, e) for idx, e in exps.items() if e != 0))


def poly_mul(a: Poly, b: Poly) -> Poly:
    """Multiply two polynomials."""
    out: Poly = poly_zero()
    for m1, c1 in a.items():
        for m2, c2 in b.items():
            mon = _mon_mul(m1, m2)
            new = sp.cancel(out.get(mon, sp.Integer(0)) + c1 * c2)
            if new == 0:
                out.pop(mon, None)
            else:
                out[mon] = new
    return out


def cc(k: int) -> sp.Expr:
    """The deformation scalar c_k = 1 - t^{2k+1}."""
    return sp.Integer(1) - T ** (2 * k + 1)


def q_gen(cf, n: int) -> Poly:
    """
    The generic creation function q^cf_n defined by the Newton recursion

        q^cf_0     = 1
        q^cf_{m+1} = (1/(m+1)) * sum_{k=0}^{floor(m/2)} 2 * cf(k) * q^cf_{m-2k}.

    `cf` is a callable mapping an index k to a Poly (the building block).
    """
    cache: Dict[int, Poly] = {}

    def rec(m: int) -> Poly:
        if m in cache:
            return cache[m]
        if m == 0:
            cache[0] = poly_one()
            return cache[0]
        prev = m - 1
        acc: Poly = poly_zero()
        for k in range(prev // 2 + 1):
            term = poly_scale(sp.Integer(2), poly_mul(cf(k), rec(prev - 2 * k)))
            acc = poly_add(acc, term)
        result = poly_scale(sp.Rational(1, m), acc)
        cache[m] = result
        return result

    return rec(n)


def q(n: int) -> Poly:
    """One-row Schur Q-function q_n = Q_(n), built from cf(k) = X_k."""
    return q_gen(poly_var, n)


def qt(n: int) -> Poly:
    """t-deformed one-row function, built from cf(k) = (1 - t^{2k+1}) X_k."""
    return q_gen(lambda k: poly_scale(cc(k), poly_var(k)), n)


def phi_t(a: Poly) -> Poly:
    """
    The plethystic endomorphism phi_t: for each monomial prod_k X_k^{e_k},
    multiply the coefficient by prod_k (1 - t^{2k+1})^{e_k}, leaving the
    monomial fixed.
    """
    out: Poly = poly_zero()
    for mon, coeff in a.items():
        factor: sp.Expr = sp.Integer(1)
        for idx, e in mon:
            factor *= cc(idx) ** e
        out = poly_add(out, {mon: sp.cancel(coeff * factor)})
    return out


def poly_eq(a: Poly, b: Poly) -> bool:
    """Decide equality of two polynomials over Q(t)."""
    diff = poly_add(a, poly_scale(sp.Integer(-1), b))
    return len(diff) == 0


def pretty(a: Poly) -> str:
    """Render a polynomial in readable p_{2k+1} notation."""
    if not a:
        return "0"
    parts = []
    for mon in sorted(a.keys(), key=lambda m: (sum(e for _, e in m), m)):
        coeff = a[mon]
        if not mon:
            parts.append(f"({sp.simplify(coeff)})")
            continue
        factors = "*".join(
            f"p{2 * idx + 1}" + (f"^{e}" if e != 1 else "") for idx, e in mon
        )
        parts.append(f"({sp.simplify(coeff)})*{factors}")
    return " + ".join(parts)


def main() -> None:
    print("=" * 72)
    print("Plethystic triviality of the shifted t-Schur basis")
    print("=" * 72)
    print()
    print("One-row Schur Q-functions q_n (in odd power sums p1=X0, p3=X1, ...):")
    for n in range(6):
        print(f"  q_{n} = {pretty(q(n))}")
    print()

    print("Verifying the creation-part intertwining  qt_n = phi_t(q_n):")
    all_ok = True
    for n in range(9):
        lhs = qt(n)
        rhs = phi_t(q(n))
        ok = poly_eq(lhs, rhs)
        all_ok = all_ok and ok
        print(f"  n={n}:  qt_n == phi_t(q_n)  ->  {ok}")
    print()
    print(f"All checked rows agree: {all_ok}")
    print()

    print("Illustration for n=3 (note the (1 - t^k) factors appearing):")
    print(f"  q_3        = {pretty(q(3))}")
    print(f"  qt_3       = {pretty(qt(3))}")
    print(f"  phi_t(q_3) = {pretty(phi_t(q(3)))}")
    print()
    print("Here q_3 = (4/3)*p1^3 + (2/3)*p3, and applying phi_t scales p1^3 by")
    print("(1 - t)^3 and p3 by (1 - t^3), exactly matching qt_3.")


if __name__ == "__main__":
    main()
